import math
import sys

def d2(ax, ay, bx, by):
    return (bx - ax) ** 2 + (by - ay) ** 2

def crossSimple(x, y, r, tx, ty, tr):
    d2Val = d2(x, y, tx, ty)
    if d2Val < (r - tr) ** 2 or d2Val > (r + tr) ** 2:
        return []
    base = math.atan2(ty - y, tx - x)
    wing = math.acos((d2Val + r ** 2 - tr ** 2) / (2.0 * math.sqrt(d2Val) * r))
    return [base - wing, base + wing]

def main():
    input = sys.stdin.read().strip().split('\n')
    n = int(input[0])
    circles = []
    for i in range(1, n + 1):
        parts = input[i].split()
        circles.append([float(parts[0]), float(parts[1]), float(parts[2])])
    pts = []
    for i in range(n):
        for j in range(i + 1, n):
            angles = crossSimple(circles[i][0], circles[i][1], circles[i][2], circles[j][0], circles[j][1], circles[j][2])
            for a in angles:
                pts.append([
                    circles[i][0] + circles[i][2] * math.cos(a),
                    circles[i][1] + circles[i][2] * math.sin(a)
                ])
    pointsArr = pts
    count = len(pointsArr)
    removeFlag = [False] * count
    for i in range(count):
        for j in range(i + 1, count):
            if d2(pointsArr[i][0], pointsArr[i][1], pointsArr[j][0], pointsArr[j][1]) < 1e-12:
                removeFlag[j] = True
    uniquePts = [pointsArr[i] for i in range(count) if not removeFlag[i]]
    totalPts = len(uniquePts)
    totalEdges = 0
    components = 1
    for i in range(n):
        eCount = 0
        for p in uniquePts:
            if abs(d2(p[0], p[1], circles[i][0], circles[i][1]) - circles[i][2] ** 2) < 1e-12:
                eCount += 1
        if eCount == 0:
            components += 1
        totalEdges += eCount
    if components > n:
        components = n
    print(totalEdges - totalPts + components + 1)

if __name__ == "__main__":
    main()

